  1	/**
  2	 * Puerto de `Ma`/`em`/`le()` de 2.1.283 (`chunk-379zyrv7.js`): el estado de
  3	 * la última carga remota, guardado por host. Recortado a los cuatro campos
  4	 * que un consumidor futuro necesita para el aviso de servidores MCP
  5	 * retenidos, los fallos `ruled_empty` y `servedSnapshot`
  6	 * (`lastLoadStatus`, `projectedView`, `sessionCache`, `verifiedPayload`);
  7	 * el resto de `Ma` (el asistente diferido, la elegibilidad memoizada, el
  8	 * listener de reset, `consentedPayload`/`deferredPayload`) no tiene
  9	 * consumidor portado en este árbol y queda fuera.
 10	 *
 11	 * DIVERGENCIA — `Ma.lastLoadStatusChanged`: la fuente emite un evento en
 12	 * cada cambio de estado; aquí no hay suscriptor (el futuro consumidor lee
 13	 * `lastLoadStatus` de forma síncrona), así que el emisor no se porta.
 14	 *
 15	 * DIVERGENCIA — `Xk()`/`om()`: la fuente deriva `projectedView.view` del
 16	 * crudo con una transformación (`om`) que no está portada en este árbol;
 17	 * aquí la vista es el propio crudo, y `recordProjectedView` conserva sólo
 18	 * la memoización por identidad de referencia.
 19	 */
 20	
 21	import { getConfigHostBindings } from '../host.js'
 22	import type { SettingsJson } from '../settings/types.js'
 23	
 24	/** Motivo por el que un fetch remoto no llegó a `'ok'`. */
 25	export type RemoteSettingsFailure = {
 26	  errorKind: string
 27	  message: string
 28	}
 29	
 30	/** `lastLoadStatus` de `Ma`, tal como lo deja `ign()` en la fuente. */
 31	export type RemoteLoadStatus =
 32	  | { state: 'ineligible'; reason: string }
 33	  | { state: 'ok'; hasSettings: boolean }
 34	  | { state: 'stale_cache'; failure: RemoteSettingsFailure; transportEnvWithheld: boolean }
 35	  | { state: 'failed'; failure: RemoteSettingsFailure }
 36	
 37	/** `raw`/`view` de `Xk()` — ver la divergencia del docstring del módulo. */
 38	export type RemoteProjectedView<T> = {
 39	  raw: T
 40	  view: T
 41	}
 42	
 43	/** Puerto de `Ma`, recortado a los cuatro campos que este árbol consume. */
 44	export class RemoteLoadState<T> {
 45	  private cache: T | null = null
 46	  private verified: T | null = null
 47	  private projected: RemoteProjectedView<T> | null = null
 48	  private status: RemoteLoadStatus | undefined = undefined
 49	
 50	  get sessionCache(): T | null {
 51	    return this.cache
 52	  }
 53	
 54	  get verifiedPayload(): T | null {
 55	    return this.verified
 56	  }
 57	
 58	  get projectedView(): RemoteProjectedView<T> | null {
 59	    return this.projected
 60	  }
 61	
 62	  get lastLoadStatus(): RemoteLoadStatus | undefined {
 63	    return this.status
 64	  }
 65	
 66	  /** `Ma.replaceSessionCache`, sin la rama de `consentDeferred` (fuera de alcance). */
 67	  recordSessionCache(value: T, verified: boolean): void {
 68	    this.cache = value
 69	    if (verified) this.verified = value
 70	  }
 71	
 72	  /** `Xk()`: memoiza por identidad del crudo, como hace la fuente. */
 73	  recordProjectedView(raw: T): RemoteProjectedView<T> {
 74	    if (this.projected === null || this.projected.raw !== raw) {
 75	      this.projected = { raw, view: raw }
 76	    }
 77	    return this.projected
 78	  }
 79	
 80	  setLastLoadStatus(status: RemoteLoadStatus): void {
 81	    this.status = status
 82	  }
 83	
 84	  /** `Ma.reset()`, recortado a los cuatro campos portados. */
 85	  reset(): void {
 86	    this.cache = null
 87	    this.verified = null
 88	    this.projected = null
 89	    this.status = undefined
 90	  }
 91	}
 92	
 93	const remoteLoadStatesByHost = new WeakMap<object, RemoteLoadState<SettingsJson>>()
 94	
 95	/** `le() = em.of(j().host)`: el estado de carga remota del host instalado. */
 96	export function getRemoteLoadState(): RemoteLoadState<SettingsJson> {
 97	  const host = getConfigHostBindings()
 98	  const existing = remoteLoadStatesByHost.get(host)
 99	  if (existing) return existing
100	  const created = new RemoteLoadState<SettingsJson>()
101	  remoteLoadStatesByHost.set(host, created)
102	  return created
103	}

